TLM.f("Sancti/06-21",{"officium":"S. Aloisii Gonzagæ Confessoris","rule":["vide C5;","Gloria"],"fallback":"Commune/C5","from":{"Lectio":"Commune/C5","Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Ps 8:6"},{"k":"text","la":"Minuísti eum paulo minus ab Angelis: glória et honóre coronásti eum."},{"k":"ref","la":"Ps 148:2"},{"k":"text","la":"Laudáte Dóminum, omnes Angeli ejus: laudáte eum, omnes virtútes ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Minuísti eum paulo minus ab Angelis: glória et honóre coronásti eum."}],"Oratio":[{"k":"text","la":"Cœléstium donórum distribútor, Deus, qui in angélico júvene Aloísio miram vitæ innocéntiam pari cum pœniténtia sociásti: ejus méritis et précibus concéde; ut, innocéntem non secúti, pœniténtem imitémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 31:8-11"},{"k":"text","la":"Beátus vir, qui invéntus est sine mácula, et qui post aurum non ábiit, nec sperávit in pecúnia et thesáuris. Quis est hic, et laudábimus eum? fecit enim mirabília in vita sua. Qui probátus est in illo, et perféctus est, erit illi glória ætérna: qui potuit tránsgredi, et non est transgréssus: fácere mala, et non fecit: ídeo stabilíta sunt bona illíus in Dómino, et eleemósynas illíus enarrábit omnis ecclésia sanctórum."}],"Graduale":[{"k":"ref","la":"Ps 70:5-6"},{"k":"text","la":"Dómine, spes mea a juventúte mea: in te confirmátus sum ex útero: de ventre matris meæ tu es protéctor meus."},{"k":"ref","la":"Ps 40:13"},{"k":"text","la":"Me autem propter innocéntiam suscepísti: et confirmásti me in conspéctu tuo in ætérnum."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 64:5"},{"k":"text","la":"Beátus, quem elegísti et assumpsísti: inhabitábit in átriis tuis. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 64:5"},{"k":"text","la":"Beátus, quem elegísti et assumpsísti: inhabitábit in átriis tuis. Allelúja."},{"k":"ref","la":"Ps 70:18"},{"k":"text","la":"Deus, docuísti me a juventúte mea: et usque nunc pronuntiábo mirabília tua. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 22:29-40"},{"k":"text","la":"In illo témpore: Respóndens Jesus, ait sadducæis: Errátis, nesciéntes Scriptúras neque virtútem Dei. In resurrectióne enim neque nubent neque nubéntur: sed erunt sicut Angeli Dei in cœlo. De resurrectióne autem mortuórum non legístis, quod dictum est a Deo dicénte vobis: Ego sum Deus Abraham et Deus Isaac et Deus Jacob? Non est Deus mortuórum, sed vivéntium. Et audiéntes turbæ, mirabántur in doctrína ejus. Pharisæi autem audiéntes, quod siléntium imposuísset sadducæis, convenérunt in unum: et interrogávit eum unus ex eis legis doctor, tentans eum: Magíster, quod est mandátum magnum in lege? Ait illi Jesus: Díliges Dóminum, Deum tuum, ex toto corde tuo, et in tota ánima tua, et in tota mente tua. Hoc est máximum et primum mandátum. Secúndum autem símile est huic: Díliges próximum tuum, sicut teípsum. In his duóbus mandátis univérsa lex pendet et Prophétæ."}],"Offertorium":[{"k":"ref","la":"Ps 23:3-4"},{"k":"text","la":"Quis ascéndet in montem Dómini, aut quis stabit in loco sancto ejus? Innocens mánibus, et mundo corde."}],"Secreta":[{"k":"text","la":"Cœlésti convívio fac nos, Dómine, nuptiáli veste indútos accúmbere: quam beáti Aloísii pia præparátio et juges lácrimæ inæstimabílibus ornábant margarítis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 77:24-25"},{"k":"text","la":"Panem cœli dedit eis: panem Angelórum manducávit homo."}],"Postcommunio":[{"k":"text","la":"Angelórum esca nutrítos, angélicis étiam, Dómine, da móribus vívere: et ejus, quem hódie cólimus, exémplo in gratiárum semper actióne manére."},{"k":"macro","name":"Per Dominum"}]},"hr":{"40395f1379426141":{"t":"Ps 8, 6, Ps 148, 2\n(Ps 8, 6) Uzveličao si ga malo manje nego anđele, ovjenčao si ga slavom i čašću. (Ps 148, 2) Hvalite Gospodina, svi anđeli njegovi, hvalite ga, sve vojske njegove.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 8, 6) Uzveličao si ga malo manje nego anđele, ovjenčao si ga slavom i čašću.","kn":"(Ps. 8, 6). Učinio si ga malo manjim od anđela, slavom si ga i čašću okrunio. (Ps. 148, 2). Hvalite Boga svi anđeli njegovi, hvalite ga sve vojske njegove. Slava Ocu . . . Učinio . . .","knRef":"Kniewald 1942, str. 600–601 (snimka 301) (OCR)"},"068511f334604777":{"t":"<i>Pomolimo se</i>.\nBože, djelitelju nebeskih dobara, koji si u anđeoskom mladiću Alojziju združio divnu nevinost života s jednakom pokorom, daj da ga, po njegovim zaslugama i zagovoru, slijedimo u pokori, kad ga nismo slijedili u nevinosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, djelitelju nebeskih darova, koji si u anđeoskom mladiću Alojziju udružio divnu nevinost života s jednakom pokorom, dopusti po njegovim zaslugama i molitvama, da nasljeđujemo pokornika, koji ne pođoemo za njim nevinim, po","knRef":"Kniewald 1942, str. 600–601 (snimka 301) (OCR)"},"d0743eab00685bfc":{"t":"Sir 31, 8-11\nČitanje knjige Mudrosti. Blago čovjeku koji se nađe bez ljage i ne teži za zlatom, niti se uzda u novac i blago. Tko je taj, da ga pohvalimo? U svojem je životu učinio divna djela. Tko je u tome prokušan i savršen bit će uvijek slavan. Mogao je sagriješiti, ali nije sagriješio, učiniti zlo, ali nije počinio. Zato priznaje njegova djela Gospodin, a njegovih će se milostinja sjećati sve skupine svetih.","kn":"Čitanje Knjige mudrosti (Crkv. 31, 8-11). Blago čovjeku, koji se našao bez ljage i koji ne ide za zlatom niti se uzda u novac i blago. Tko je taj, da ga hvalimo? Jer je u svom životu učinio divna djela. Vječno će biti slavan, koji je u tom prokušan i savršen; mogao je sagriješiti, a nije sagriješio, i učiniti zlo, a nije učinio. Zato su njegova dobra priznata od Gospodina, i njegove će milostinje kazivati čitav zbor svetih. t!82","knRef":"Kniewald 1942, str. 680–681 (snimka 341) (OCR)"},"513d0d3dbdb67983":{"t":"Ps 70, 5-6, Ps 40, 13\n(Ps 70, 5-6) Gospodine, nado moja od mladosti moje! Tebi pripadam još od majčina krila, već od prvih dana mojih ti si mi zaštitnik. (Ps 40, 13) Primio si me radi moje nevinosti, dao si mi da stalno budem uza te.\n\nPs 64, 5\n<i>Aleluja</i>, <i>aleluja</i>.\nBlago onome koga si ti odabrao i primio da prebiva u dvorima tvojim. <i>Aleluja</i>.","kn":"(Ps. 70, 5, 6). Gospodine, nado moja od mladosti moje. Tebe se držah od matermjeg krila, već od prve mladosti Ti si branič moj' S' nr^d moje čuvaj me i utvrdi\n\nAleluja, aleluja (Ps. 64, 5). Blago onome, koga Ti odabireš i primaš da stanuje u dvorovima Tyojim, aleluja","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"},"14ebd89848476dee":{"t":"Mt 22, 29-40\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus saducejima: Varate se, jer ne shvaćate ni pisma ni Božje moći. O uskrsnuću niti će se ženiti niti udavati, nego će biti kao Božji anđeli na nebu. Zar niste čitali, što vam je Bog objavio o uskrsnuću mrtvih: Ja sam Bog Abrahama, Bog Izaka i Bog Jakova? Dakle, nije Bog mrtvih, nego živih. Kad je.narod to čuo, divio se njegovoj nauci. A kad su farizeji dočuli da je ušutkao saduceje, sastanu se i jedan njihov pismoznanac, da ga iskuša, upita ga: Učitelju, koja je najveća zapovijed u zakonu? Isus mu odgovori: Ljubi Gospodina Boga svojega svim srcem svojim, svom dušom svojom, svom mišlju svojom. Ovo je najveća i prva zapovijed. A druga je ovoj jednaka: Ljubi bližnjega svojega kao samoga sebe. O ovim dvjema zapovijedima ovisi sav zakon i proroci.","kn":"U ono vrijeme reče Isus saducejima: Varate se j°r ne znate ni Pisma ni Božje moći. o uskrsnuću anđe^ udavati, nego će biti kao Božji mrtvih ^ ° uskrsnuću mrtvih, sto vam je bilo rečeno od Boga- Ja sam Boe mrt^ Jakovljev? Nije Bog mrtvih, nego živih. Kad je to narod čuo di! da je ušutkao saduceje, sastanu se, i jedan od niih Sju 'ko?r ga upita,: Uči^ telju, koja je najveća zapovijed u zakonu? Isus mu odgovori: Ljubi Gospodina Boga svoga svim svojom. Ovo je najveća i prva zapovijed. A druga Sv. PauHn 22. VI. je ovoj jednaka: Ljubi svoga bližnjega kao samoga sebe. O ovim dvjema zapovjedimo ovisi sav zakon i proroci.","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"},"39bd06e335e596e6":{"t":"Ps 23, 3-4\nTko će uzaći na goru Gospodnju, tko će stati na svetom mjestu njegovu? Onaj koji je nevinih ruku i čista srca.","kn":"(Ps. 23, 3, 4). Tko će uzaći na goru Gospodnju? Tko će stati na svetom mjestu njegovu? U koga su nevine ruke i čisto srce!","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"},"b4c71028550d81c6":{"t":"Daj nam, Gospodine, da dok sjedimo na nebeskoj gozbi budemo obučeni u nebesko ruho što su ga pobožna priprava i neprestane suze blaženog Alojzija uresili dragocjenim biserima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Učini, Gospodine, da sjedimo za nebeskom gozbom odjeveni u svadbeno ruho, koje^ su bogo- Ijubna priprava i nepresušne suze bi. Alojzija ukrasile dragocjenim biserima, po G. n.","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"0146aaeaf4283345":{"t":"Ps 77, 24-25\nKruh s neba dao si njima, ljudi blaguju kruh anđeoski.","kn":"(Ps. 77, 24, 25). Dao si im kruha s nebesa, čovjek blagova kruh anđeoski.","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"},"a392167b70f1473e":{"t":"<i>Pomolimo se</i>.\nDaj, Gospodine, nama koji smo nahranjeni anđeoskim jelom i živjeti anđeoskim životom, i ostati u trajnom zahvaljivanju po primjeru onoga kojeg danas štujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da mi, koje si nahranio anđeoskim kruhom, živimo anđeoskim životom i da po primjeru svetog Alojzija, kojega danas štujemo, vazda ustrajemo u zahvalnosti, po G. n.","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"}}});
